/* ------------------------------------------------------------------ */
/* Hero animation: the graph from the Dijkstra worked example draws    */
/* itself, then a marker travels the cheapest route from A to E.       */
/* Positions are in SVG units (viewBox 520 x 300).                      */
/* ------------------------------------------------------------------ */
const V = {
  A: { x: 50, y: 150 },
  B: { x: 190, y: 60 },
  C: { x: 190, y: 240 },
  D: { x: 340, y: 150 },
  E: { x: 470, y: 150 },
};

const EDGES = [
  ["A", "B", 4],
  ["A", "C", 2],
  ["B", "C", 1],
  ["B", "D", 5],
  ["C", "D", 8],
  ["C", "E", 10],
  ["D", "E", 2],
];

// Cheapest route A -> C -> B -> D -> E (cost 2 + 1 + 5 + 2 = 10)
const ROUTE = ["A", "C", "B", "D", "E"];

const VERTEX_DELAY = 0.15; // seconds between each vertex appearing
const EDGE_START = 0.9; // edges start drawing after the vertices
const EDGE_STEP = 0.18;
const ROUTE_START = 3.0; // highlighted route starts after the whole graph is drawn
const ROUTE_STEP = 0.7;

function mid(a, b) {
  return { x: (V[a].x + V[b].x) / 2, y: (V[a].y + V[b].y) / 2 };
}

function HeroGraph() {
  const routeEdges = ROUTE.slice(0, -1).map((from, i) => [from, ROUTE[i + 1]]);
  const dotDelay = ROUTE_START + ROUTE_STEP * (routeEdges.length) + 0.2;

  return (
    <svg
      viewBox="0 0 520 300"
      role="img"
      aria-label="A weighted graph with five vertices. The cheapest route from A to E, through C, B and D, has a total cost of 10."
      className="intro-graph h-auto w-full"
    >
      {/* edges */}
      {EDGES.map(([a, b], i) => (
        <line
          key={`${a}${b}`}
          x1={V[a].x}
          y1={V[a].y}
          x2={V[b].x}
          y2={V[b].y}
          pathLength="1"
          className="intro-edge"
          style={{ animationDelay: `${EDGE_START + i * EDGE_STEP}s` }}
        />
      ))}

      {/* highlighted route, drawn on top once the graph is complete */}
      {routeEdges.map(([a, b], i) => (
        <line
          key={`r${a}${b}`}
          x1={V[a].x}
          y1={V[a].y}
          x2={V[b].x}
          y2={V[b].y}
          pathLength="1"
          className="intro-route"
          style={{ animationDelay: `${ROUTE_START + i * ROUTE_STEP}s` }}
        />
      ))}

      {/* weight labels */}
      {EDGES.map(([a, b, w], i) => {
        const m = mid(a, b);
        return (
          <g
            key={`w${a}${b}`}
            className="intro-fade"
            style={{ animationDelay: `${EDGE_START + 0.4 + i * EDGE_STEP}s` }}
          >
            <circle cx={m.x} cy={m.y} r="12" className="intro-weight-bg" />
            <text x={m.x} y={m.y + 4.5} textAnchor="middle" className="intro-weight">
              {w}
            </text>
          </g>
        );
      })}

      {/* vertices */}
      {Object.entries(V).map(([id, p], i) => (
        <g key={id} className="intro-vertex" style={{ animationDelay: `${i * VERTEX_DELAY}s` }}>
          <circle cx={p.x} cy={p.y} r="22" className="intro-vertex-ring" />
          <text x={p.x} y={p.y + 6} textAnchor="middle" className="intro-vertex-label">
            {id}
          </text>
        </g>
      ))}

      {/* travelling marker */}
      <circle
        r="7"
        cx="0"
        cy="0"
        className="intro-dot"
        style={{ animationDelay: `${dotDelay}s` }}
      />

      {/* running total, appears when the marker arrives */}
      <g className="intro-total" style={{ animationDelay: `${ROUTE_START + ROUTE_STEP * routeEdges.length}s` }}>
        <rect x="372" y="262" width="136" height="28" rx="14" className="intro-total-bg" />
        <text x="440" y="281" textAnchor="middle" className="intro-total-text">
          A to E costs 10
        </text>
      </g>
    </svg>
  );
}

